    "FeGly+"        : "FeGly<sup>+</sup>",
    "Fe(Gly)2(aq)"  : "Fe(Gly)<sub>2</sub>",
    "Fe(NH3)(2+)"   : "Fe(NH<sub>3</sub>)<sup>2+</sup>",
