    "Gly-"          : "Gly<sup>−</sup>",
    "NH3"           : "NH<sub>3</sub>",
    "H+"            : "H<sup>+</sup>",
}
def pretty(lbl):
    core = lbl.replace("[Cu(II)] ", "").replace("[Cu(I)] ", "") \
              .replace("[Fe(III)] ", "").replace("[Fe(II)] ", "")
    return _PRETTY.get(core, core)

def pretty_bracket(lbl):
    """Also prefix the oxidation state hint if present."""
    if lbl.startswith("[Cu(II)] "):
        return "Cu(II) " + pretty(lbl)
    if lbl.startswith("[Cu(I)] "):
        return "Cu(I) " + pretty(lbl)
    if lbl.startswith("[Fe(III)] "):
        return "Fe(III) " + pretty(lbl)
    if lbl.startswith("[Fe(II)] "):
        return "Fe(II) " + pretty(lbl)
    return pretty(lbl)

# --------------------------------------------------------------------------
# Build DB rows for the tables
# --------------------------------------------------------------------------
def _ligand_str(stoich):
    if not stoich:
        return "—"
    parts = []
    for lig, n in stoich.items():
        base = pretty(lig)
        if n == 1:
            parts.append(base)
        else:
            parts.append(f"{n} {base}")
    return " + ".join(parts)

def db_rows(db, cation_symbol):
    rows = []
    for name, (lb, st) in db.items():
        if not st:
            reaction = f"({pretty(name)} is the free {cation_symbol})"
        else:
            reaction = f"{cation_symbol} + {_ligand_str(st)} ⇌ {pretty(name)}"
        rows.append((pretty(name), reaction, f"{lb:+.2f}" if lb != 0 else "0.00"))
    return rows

