def slice_row(pH):
    ca = cu_analysis(pH)
    fa = fe_analysis(pH)
    def seq2html(seq):
        cells = []
        for name, E in seq:
            core = pretty_bracket(name)
            if E is None or math.isinf(E):
                cells.append(f"<span class='pill top'>{core}</span>")
            else:
                cells.append(
                    f"<span class='pill'>{core}</span>"
                    f"<span class='eline'>E&nbsp;=&nbsp;{E:+.3f}&nbsp;V</span>"
                )
        return "<div class='chain'>" + "".join(cells) + "</div>"
    return (f"<tr><th scope='row'>{pH:g}</th>"
            f"<td>{seq2html([(n, E) for n, E in ca['seq']])}</td>"
            f"<td>{seq2html([(n, E) for n, E in fa['seq']])}</td>"
            f"</tr>")

partition_rows_html = "\n".join(slice_row(p) for p in
