def junctions_html(entries, tag):
    rows = []
    for pH, E, prev, curr in entries:
        old = " → ".join(pretty_bracket(x) for x in prev)
        new = " → ".join(pretty_bracket(x) for x in curr)
        rows.append(
            f"<tr><td class='num'>{pH:.2f}</td>"
            f"<td class='num'>{E:+.3f}</td>"
            f"<td><span class='old'>{old}</span><br>"
            f"<span class='new'>{new}</span></td></tr>"
        )
    return "\n".join(rows)

