    "%E0_CU2_CU1%"     : f"{E0_Cu2_Cu1:+.3f}",
    "%E0_CU1_CU%"      : f"{E0_Cu1_Cu:+.3f}",
    "%E0_FE3_FE2%"     : f"{E0_Fe3_Fe2:+.3f}",
    "%E0_FE2_FE%"      : f"{E0_Fe2_Fe:+.3f}",
    "%E0_FE3_FE%"      : f"{E0_Fe3_Fe:+.3f}",
    "%IMG_MAIN%"       : img_main,
    "%IMG_SUPPORT%"    : img_support,
