# Substitute the big base64 blobs LAST to keep other .replace() lookups fast
for k in sorted(substitutions.keys(), key=lambda x: 0 if not x.startswith("%IMG") else 1):
    HTML = HTML.replace(k, substitutions[k])

with open(OUT, "w") as f:
    f.write(HTML)

print(f"wrote {OUT}")
print(f"size: {os.path.getsize(OUT)/1024:.1f} kB")

input.old_str:
HTML = r"""<!DOCTYPE html>
<html lang="en">
<head>
